/** Explicit standalone-server acceptance through actual controls and DocumentsUI.
 * Reads existing selected users only; never installs, creates, resets or mutates a server.
 * Reflection reads retained export state for byte assertions, never invokes a UI handler.
 * The separately installed probe app provides independent-UID traffic evidence. */
@RunWith(AndroidJUnit4.class)
public final class ConnectionCollectionJourneyIntegrationTest {
    private final UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());
    private UiObject2 visible(BySelector selector,long timeout){UiObject2 view=device.wait(Until.findObject(selector),timeout);assertNotNull("Required visible collection control is missing",view);return view;}
    private void phase(PrivateAdministrationFixture f,String value)throws Exception{f.receipt("connection-collection-journey-progress.json",new JSONObject().put("phase",value));}
    private static Gateway node(List<Gateway> nodes,String id){for(Gateway n:nodes)if(n.get("id").equals(id))return n;return null;}
    private static String hash(byte[] bytes)throws Exception{return PrivateAdministrationFixture.hash(bytes);}
    private static String assetHash(Context c,String name)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getAssets().open(name)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)digest.update(b,0,n);}StringBuilder value=new StringBuilder();for(byte b:digest.digest())value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
    private static Map<String,String> nativeSnapshot(Context c)throws Exception{Map<String,String> values=new TreeMap<>();File root=new File(c.getNoBackupFilesDir(),"vpn-profiles");File[] files=root.listFiles();if(files!=null)for(File file:files){assertFalse("Do not traverse profile links",Files.isSymbolicLink(file.toPath()));if(file.isFile())values.put(file.getName(),PrivateAdministrationFixture.hash(file));}return values;}
    private static String userSnapshot(JSONObject status)throws Exception{JSONArray users=status.getJSONArray("users");TreeMap<String,String> values=new TreeMap<>();for(int i=0;i<users.length();i++){JSONObject u=users.getJSONObject(i);values.put(u.getString("login"),u.optString("person")+"\0"+u.optString("device")+"\0"+u.optBoolean("enabled",true));}return hash(values.toString().getBytes(StandardCharsets.UTF_8));}
    private static JSONObject read(Context c,Gateway owner,String action,String login)throws Exception{JSONObject request=new JSONObject().put("action",action).put("protocol",owner.get("protocol"));if(!login.isEmpty())request.put("login",login).put("name",login);try(Ssh ssh=new Ssh(owner);InputStream recipe=c.getAssets().open("single_bundle.zip")){return ssh.single(recipe,request);}}
    private static String accountLabel(JSONObject user){String login=user.optString("login"),person=user.optString("person"),device=user.optString("device"),label=person.isEmpty()?login:person;if(!device.isEmpty()&&!device.equals(label)&&!device.equals(login))label+=" · "+device;return label.equals(login)?login:label+" · "+login;}
    private void downloads(){
        // Scope the root choice to the actual drawer; Downloads also names the
        // toolbar behind it. No file is tapped until that overlay has gone.
        BySelector selector=By.res("com.android.documentsui","drawer_roots");UiObject2 drawer=device.findObject(selector);
        if(drawer==null){UiObject2 roots=device.findObject(By.desc("Show roots"));if(roots==null)return;roots.click();drawer=visible(selector,10000);}
        drawer=device.wait(Until.findObject(selector.hasDescendant(By.text("Downloads"))),10000);assertNotNull("Downloads root did not finish loading in the system drawer",drawer);UiObject2 downloads=drawer.findObject(By.text("Downloads"));assertNotNull("Downloads root is missing from the system drawer",downloads);downloads.click();
        assertTrue("System document drawer did not close",Boolean.TRUE.equals(device.wait(Until.gone(selector),10000)));device.waitForIdle(1000);
    }
    private void saveDocument(String filename)throws Exception{
        visible(By.pkg("com.android.documentsui"),15000);downloads();visible(By.clazz(EditText.class).enabled(true),10000).setText(filename);
        for(int attempt=0;attempt<2;attempt++){device.waitForIdle(1500);assertEquals(filename,visible(By.clazz(EditText.class).enabled(true),10000).getText());UiObject2 save=visible(By.pkg("com.android.documentsui").text(Pattern.compile("Save",Pattern.CASE_INSENSITIVE)).enabled(true).clickable(true),10000);android.graphics.Rect bounds=save.getVisibleBounds();assertTrue(bounds.width()>0&&bounds.height()>0);assertTrue(device.click(bounds.centerX(),bounds.centerY()));if(Boolean.TRUE.equals(device.wait(Until.gone(By.pkg("com.android.documentsui")),5000)))return;}
        throw new AssertionError("The unchanged system Save action did not finish; do not replay server operations");
    }
    private String chooseDocument(String filename){
        visible(By.pkg("com.android.documentsui"),15000);downloads();device.waitForIdle(1000);
        UiObject2 file=visible(By.pkg("com.android.documentsui").text(Pattern.compile(Pattern.quote(filename)+"(?:\\.json)?")),15000);String actual=file.getText();android.graphics.Rect bounds=file.getVisibleBounds();
        assertTrue("The selected collection has no visible tap target",bounds.width()>0&&bounds.height()>0);assertTrue("The selected collection tap was not injected",device.click(bounds.centerX(),bounds.centerY()));
        assertTrue("The system document picker did not return the selected collection",Boolean.TRUE.equals(device.wait(Until.gone(By.pkg("com.android.documentsui")),15000)));return actual;
    }
    private static ConnectionCollectionState retained(ActivityScenario<RookstrideActivity> screen){AtomicReference<ConnectionCollectionState> found=new AtomicReference<>();screen.onActivity(a->{try{Field f=RookstrideActivity.class.getDeclaredField("collectionState");f.setAccessible(true);found.set((ConnectionCollectionState)f.get(a));}catch(Exception e){throw new AssertionError(e);}});return found.get();}
    private static Set<String> ids(List<Gateway> nodes){Set<String> values=new HashSet<>();for(Gateway n:nodes)values.add(n.get("id"));return values;}
    private static void clientOnly(Gateway client){assertTrue(client.data.optBoolean("clientOnly"));assertFalse(client.isPair());assertFalse(client.data.optBoolean("adminAccess"));assertEquals("",client.sshPassword);assertEquals("",client.privateKey);for(String key:new String[]{"admin","adminKey","fingerprint","sshRoute","grantId","authorityId"})assertTrue("Imported access contains server authority",client.get(key).isEmpty());}
    private void consent(){UiObject2 background=device.findObject(By.text("Connect now"));if(background!=null)background.click();UiObject2 consent=device.wait(Until.findObject(By.pkg("com.android.vpndialogs").res("android:id/button1")),5000);if(consent!=null)consent.click();}
    private static void disconnected(Context c,String protocol)throws Exception{long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){NativeVpn.Status status=NativeVpn.status(c,protocol);if(!status.state.equals("connecting")&&!status.state.equals("checking")&&!status.state.equals("connected")&&!status.state.equals("limited")&&!status.state.equals("reconnecting")&&!status.state.equals("disconnecting"))return;Thread.sleep(150);}throw new IOException("The test tunnel did not stop; preserve imported profiles for review");}
    private static void restorePreferences(SharedPreferences target,Map<String,?> before){SharedPreferences.Editor edit=target.edit().clear();for(Map.Entry<String,?> entry:before.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,(Set<String>)value);else throw new AssertionError("Unsupported preference type");}assertTrue(edit.commit());}

    @Test public void visibleExistingUsersSaveOneFileImportAllAndConnectBothWithoutServerMutation()throws Exception{
        PrivateAdministrationFixture f=PrivateAdministrationFixture.load("connection-collection-journey","allow_connection_collection_ui");JSONObject plan=f.request.getJSONObject("collection_journey");
        for(String flag:new String[]{"allow_existing_profile_reads","allow_native_vpn","allow_documents_ui","allow_temporary_client_import","allow_restore_phone_catalog","allow_saved_file_with_vpn_access"})assertTrue("Explicit collection journey authorization is missing",f.request.getBoolean(flag));
        assertTrue("Only isolated test users may be connected",plan.getBoolean("exclusive_test_users"));assertFalse(DeploymentService.active());assertFalse(DeploymentService.needsLocalSave());assertFalse(ConnectionBundleImport.recoveryPending(f.context));assertEquals("all",AppRouting.read(f.context).mode);f.context.getPackageManager().getApplicationInfo("io.rookstride.probe",0);
        ConnectivityManager networks=(ConnectivityManager)f.context.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities active=networks.getNetworkCapabilities(networks.getActiveNetwork());assertFalse("Stop the previous VPN before sharing or connecting duplicate device keys",active!=null&&active.hasTransport(NetworkCapabilities.TRANSPORT_VPN));
        JSONObject recipes=plan.getJSONObject("recipe_sha256");assertEquals("The test must pin the exact packaged SSH recipe",plan.getJSONObject("recipe_sha256").getString("single_bundle.zip"),assetHash(f.context,"single_bundle.zip"));for(Iterator<String> it=recipes.keys();it.hasNext();)assertEquals("Unexpected recipe pin", "single_bundle.zip",it.next());
        Vault vault=new Vault(f.context);ArrayList<Gateway> before=vault.read();Set<String> prior=ids(before);Gateway physical=node(before,plan.getString("server_node_id"));assertNotNull(physical);assertFalse("A pair-owned entry is not a standalone collection server",physical.isPair());assertFalse(physical.data.optBoolean("clientOnly"));assertEquals(plan.getString("server_host"),physical.get("host"));assertEquals(plan.getString("server_name"),ServerProtocols.name(physical));
        for(Gateway candidate:before)assertFalse("The reviewed server is still a Double VPN member",candidate.isPair()&&(PairNodes.same(candidate,physical)||PairNodes.same(candidate.exit,physical)));
        JSONArray selections=plan.getJSONArray("connections");assertEquals("This acceptance uses one AWG and one password OpenVPN connection",2,selections.length());LinkedHashMap<String,JSONObject> selected=new LinkedHashMap<>(),expected=new LinkedHashMap<>();Map<String,Gateway> owners=new HashMap<>();Map<String,String> usersBefore=new HashMap<>();Set<String> expectedInstalled=new HashSet<>();JSONArray expectedIds=plan.getJSONArray("installed_protocols");for(int i=0;i<expectedIds.length();i++)expectedInstalled.add(expectedIds.getString(i));assertEquals(expectedInstalled,ServerProtocols.installed(before,physical));
        for(int i=0;i<selections.length();i++){JSONObject choice=selections.getJSONObject(i);String protocol=choice.getString("protocol"),login=choice.getString("login");assertTrue(protocol.equals("awg")||protocol.equals("openvpn"));assertNull("A protocol was selected twice",selected.put(protocol,choice));Gateway owner=node(before,choice.getString("node_id"));assertNotNull(owner);assertFalse(owner.isPair());assertFalse(owner.data.optBoolean("clientOnly"));assertFalse(owner.data.optBoolean("adminAccess"));assertTrue(ServerProtocols.sameServer(physical,owner));assertEquals(protocol,owner.get("protocol"));assertEquals(plan.getString("ssh_fingerprint"),owner.get("fingerprint"));assertEquals(choice.getString("server_instance"),owner.get("serverInstance"));assertFalse(owner.sshPassword.isEmpty()&&owner.privateKey.isEmpty());owners.put(protocol,owner);
            JSONObject status=read(f.context,owner,"status","");assertEquals(choice.getString("server_instance"),status.getString("instance"));assertTrue(status.getBoolean("running"));usersBefore.put(protocol,userSnapshot(status));JSONObject user=null;JSONArray users=status.getJSONArray("users");for(int n=0;n<users.length();n++)if(login.equals(users.getJSONObject(n).optString("login")))user=users.getJSONObject(n);assertNotNull("The fixture selects an existing VPN user",user);assertTrue(user.optBoolean("enabled",true));assertEquals(choice.getString("account_label"),accountLabel(user));if(protocol.equals("openvpn")){assertTrue(status.getBoolean("manual_sign_in"));assertFalse(choice.getString("password").isEmpty());}
            JSONObject response=read(f.context,owner,"profile",login);expected.put(protocol,ConnectionCollectionProfiles.complete(response,login,choice.optString("password"),"Fixture comparison"));
        }
        assertEquals(new HashSet<>(Arrays.asList("awg","openvpn")),selected.keySet());Map<String,String> nativeBefore=nativeSnapshot(f.context);Map<String,?> uiBefore=new HashMap<>(f.context.getSharedPreferences("rookstride-ui",0).getAll());ArrayList<Gateway> imported=new ArrayList<>();ConnectionCollectionState state=null;String operation="";JSONObject result=new JSONObject();boolean passed=false;
        try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
            phase(f,"selecting existing connections through server controls");onView(withContentDescription("Servers")).perform(click());onView(allOf(withContentDescription("Manage "+plan.getString("server_name")),isDescendantOfA(withTagValue(is((Object)("managed-server-"+physical.get("id"))))))).perform(scrollTo(),click());onView(withText("Share several connections")).perform(scrollTo(),click());
            for(String protocol:selected.keySet())onView(allOf(withText(SingleProtocols.from(protocol).title),isAssignableFrom(android.widget.CheckBox.class))).perform(scrollTo(),click());onView(withText("Next")).perform(click());
            ArrayList<String> order=new ArrayList<>(selected.keySet());order.sort(Comparator.comparing(p->SingleProtocols.from(p).title.toLowerCase(Locale.ROOT)));
            for(String protocol:order){JSONObject choice=selected.get(protocol);visible(By.text("Choose a VPN user"),90000);onView(withText("Use VPN user")).check(matches(not(isEnabled())));onView(allOf(withText(choice.getString("account_label")),isAssignableFrom(android.widget.RadioButton.class))).perform(scrollTo(),click());onView(withText("Use VPN user")).perform(click());
                long until=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<until){if(device.findObject(By.text("Include VPN password"))!=null){assertEquals("Only OpenVPN requires an operator-supplied secret here","openvpn",protocol);onView(withTagValue(is((Object)"Existing VPN password"))).perform(replaceText(choice.getString("password")));androidx.test.espresso.Espresso.closeSoftKeyboard();onView(withText("Continue")).perform(click());break;}if(device.findObject(By.text("Connections ready to share"))!=null||device.findObject(By.text("Choose a VPN user"))!=null)break;if(device.findObject(By.text("Action needs attention"))!=null)throw new AssertionError("A read-only selected-user export failed; no server command will be replayed");Thread.sleep(150);}
            }
            visible(By.text("Connections ready to share"),90000);state=retained(screen);assertNotNull(state.exportBundle);String collection=state.exportBundle;List<JSONObject> entries=ConnectionBundle.parse(collection);assertEquals(2,entries.size());Map<String,JSONObject> exported=new HashMap<>();Set<String> labels=new HashSet<>();
            for(JSONObject entry:entries){String protocol=entry.getString("format");assertEquals("The selected existing user's client bytes changed",PrivateAdministrationFixture.hash(expected.get(protocol).getString("content")),PrivateAdministrationFixture.hash(entry.getString("content")));assertTrue("Recipient names must show their protocol",entry.getString("display_name").contains(SingleProtocols.from(protocol).title));assertTrue("Recipient names must show the selected user",entry.getString("display_name").contains(selected.get(protocol).getString("login")));assertTrue("Selected connections require distinct recipient names",labels.add(entry.getString("display_name")));exported.put(protocol,entry);String administratorPassword=owners.get(protocol).sshPassword;if(!administratorPassword.isEmpty())assertFalse("An administrator secret reached the access file",collection.contains(administratorPassword));}
            // A key-based INI has no embedded account name. The review must show
            // its preserved human label, rather than only generic Device access.
            onView(withText(exported.get("awg").getString("display_name"))).check(matches(isDisplayed()));
            for(String field:new String[]{"sshPassword","adminKey","adminAccess","grantId","authorityId","pairExit"})assertFalse("Server administrator data reached an ordinary access file",collection.contains("\""+field+"\""));
            result.put("selected_existing_profiles_only",true).put("collection_sha256",hash(collection.getBytes(StandardCharsets.UTF_8))).put("no_administrator_access",true);String filename="rookstride-collection-"+UUID.randomUUID().toString().replace("-","").substring(0,10)+".rookbundle";
            phase(f,"saving the one collection through Android DocumentsUI");onView(withText("Save connection file")).perform(scrollTo(),click());saveDocument(filename);visible(By.text("Connection file saved"),15000);onView(withText("Done")).perform(click());result.put("documents_ui_save",true);
            phase(f,"importing the saved collection through the normal picker");onView(withContentDescription("VPNs")).perform(click());onView(withText("Add VPN")).perform(scrollTo(),click());onView(withText("Import a VPN")).perform(scrollTo(),click());onView(withText("Rookstride connection collection")).perform(scrollTo(),click());String actualFilename=chooseDocument(filename);visible(By.text("Import VPN connections"),15000);onView(withText(exported.get("awg").getString("display_name"))).check(matches(isDisplayed()));onView(withText("Import all")).perform(click());visible(By.text("VPN connections added"),20000);onView(withText("Done")).perform(click());
            for(Gateway client:vault.read())if(!prior.contains(client.get("id"))){clientOnly(client);assertTrue("An unrelated connection appeared during the exclusive journey",exported.containsKey(client.get("protocol")));JSONObject stored=new NativeProfileStore(f.context).read(client.get("id"));assertEquals("Imported client bytes changed",PrivateAdministrationFixture.hash(exported.get(client.get("protocol")).getString("content")),PrivateAdministrationFixture.hash(stored.getString("content")));assertEquals(exported.get(client.get("protocol")).getString("display_name"),client.get("name"));if(operation.isEmpty())operation=client.get("bundleImportId");assertFalse(operation.isEmpty());assertEquals(operation,client.get("bundleImportId"));imported.add(client);}
            assertEquals(2,imported.size());result.put("normal_picker_import_all",true).put("exact_imported_client_bytes",true);JSONArray traffic=new JSONArray();
            for(Gateway client:imported){phase(f,"connecting imported "+SingleProtocols.from(client.get("protocol")).title);onView(withContentDescription("VPNs")).perform(click());onView(withContentDescription("Open "+client.get("name"))).perform(scrollTo(),click());onView(allOf(withText("Connect"),isDescendantOfA(withTagValue(is((Object)"connection-controls"))))).perform(scrollTo(),click());consent();NativePairIntegrationTest.connected(f.context,client);JSONObject choice=selected.get(client.get("protocol"));JSONObject probe=NativePairIntegrationTest.probe(f.context,false,choice.optString("canary_url"));NativePairIntegrationTest.verifyTraffic(probe,choice.getString("expected_exit"),choice.optString("canary_token"));traffic.put(new JSONObject().put("protocol",client.get("protocol")).put("foreign_uid_https_exit_dns_ipv6",true));onView(allOf(withText("Disconnect"),isDescendantOfA(withTagValue(is((Object)"connection-controls"))))).perform(scrollTo(),click());disconnected(f.context,client.get("protocol"));}
            for(String protocol:selected.keySet()){JSONObject status=read(f.context,owners.get(protocol),"status","");assertEquals(selected.get(protocol).getString("server_instance"),status.getString("instance"));assertEquals("Sharing or importing changed existing server users",usersBefore.get(protocol),userSnapshot(status));JSONObject after=ConnectionCollectionProfiles.complete(read(f.context,owners.get(protocol),"profile",selected.get(protocol).getString("login")),selected.get(protocol).getString("login"),selected.get(protocol).optString("password"),"Fixture comparison");assertEquals("The selected server device key or configuration changed",PrivateAdministrationFixture.hash(expected.get(protocol).getString("content")),PrivateAdministrationFixture.hash(after.getString("content")));}
            result.put("traffic",traffic).put("server_users_and_selected_keys_unchanged",true).put("saved_filename",actualFilename);passed=true;
        }finally{
            for(String protocol:selected.keySet()){NativeVpn.disconnect(f.context,protocol);disconnected(f.context,protocol);}if(state!=null){long until=SystemClock.elapsedRealtime()+30000;while(state.working&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);assertFalse("A collection operation is still finishing; preserve its catalog",state.working);}
            ConnectionBundleImport.recover(f.context);ArrayList<Gateway> after=vault.read(),temporary=new ArrayList<>();Set<String> cleaned=new HashSet<>();for(Gateway client:after)if(!prior.contains(client.get("id"))){assertTrue("Preserve an unexpected non-client record for review",client.data.optBoolean("clientOnly"));assertTrue("Preserve an unexpected protocol for review",selected.containsKey(client.get("protocol")));assertEquals("Preserve a client outside the exact selected access",PrivateAdministrationFixture.hash(client.get("protocol")+"\0"+expected.get(client.get("protocol")).getString("content")),client.get("importedConnectionHash"));assertFalse("Preserve an unowned import for review",client.get("bundleImportId").isEmpty());if(!operation.isEmpty())assertEquals(operation,client.get("bundleImportId"));else operation=client.get("bundleImportId");temporary.add(client);}
            for(Gateway client:temporary){new NativeProfileStore(f.context).remove(client.get("id"));cleaned.add(client.get("id"));}
            vault.write(before);restorePreferences(f.context.getSharedPreferences("rookstride-ui",0),uiBefore);assertEquals("An original saved native profile changed",nativeBefore,nativeSnapshot(f.context));assertEquals(prior,ids(vault.read()));result.put("passed",passed).put("original_catalog_restored",true).put("original_native_profiles_unchanged",true).put("temporary_clients_removed",cleaned.size()).put("saved_file_retained_by_explicit_authorization",true);f.receipt("connection-collection-journey-result.json",result);phase(f,passed?"completed and local clients cleaned":"failed; local clients cleaned; inspect the private result before retrying");
        }
    }
}
